import{_ as a,o as i,c as l,a2 as e}from"./chunks/framework.DpXDHk3d.js";const u=JSON.parse('{"title":"11.3 接地装置的安装与检测","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-3-jie-di-zhuang-zhi-de-an-zhuang-yu-jian-ce.md","filePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-3-jie-di-zhuang-zhi-de-an-zhuang-yu-jian-ce.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-3-jie-di-zhuang-zhi-de-an-zhuang-yu-jian-ce.md"};function o(n,t,s,d,h,g){return i(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="_11-3-接地装置的安装与检测" tabindex="-1">11.3 接地装置的安装与检测 <a class="header-anchor" href="#_11-3-接地装置的安装与检测" aria-label="Permalink to &quot;11.3 接地装置的安装与检测&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>接地装置是把保护落到实处的东西:接地体(打入地下的金属棒)+ 接地线。这一节掌握接地装置的组成、接地电阻要求和检测方法(用接地电阻测量仪/接地摇表)。</p><h2 id="一、接地装置的组成" tabindex="-1">一、接地装置的组成 <a class="header-anchor" href="#一、接地装置的组成" aria-label="Permalink to &quot;一、接地装置的组成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设备外壳/中性点 ──► 接地线 ──► 接地体(接地极) ──► 大地</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部分</th><th>说明</th></tr></thead><tbody><tr><td><strong>接地体(接地极)</strong></td><td>埋入地下的金属导体(钢管、角钢、圆钢、铜棒),与大地接触</td></tr><tr><td><strong>接地线</strong></td><td>连接设备与接地体的导线(扁钢、铜线等)</td></tr><tr><td>接地装置 = 接地体 + 接地线</td><td>把设备电流可靠泄入大地</td></tr></tbody></table><h2 id="二、接地体的安装要求" tabindex="-1">二、接地体的安装要求 <a class="header-anchor" href="#二、接地体的安装要求" aria-label="Permalink to &quot;二、接地体的安装要求&quot;">​</a></h2><ul><li>接地体要<strong>深埋</strong>(埋深不小于规定深度,如 0.5~0.6 m 以上),接触良好土壤;</li><li>常用<strong>钢管/角钢/圆钢</strong>垂直打入或水平敷设,也可用<strong>扁钢、圆钢</strong>水平连接;</li><li>多个接地体之间用<strong>扁钢焊接</strong>相连,焊点要防腐;</li><li>接地体与接地线<strong>连接要可靠</strong>(焊接或专用夹子),连接处防腐处理;</li><li>土壤干燥、电阻率高时,可加<strong>降阻剂</strong>或换土。</li></ul><blockquote><p>⚠️ 判断题常考:接地体埋深要足够、连接要可靠、焊接处要防腐。</p></blockquote><h2 id="三、接地电阻的要求-必背" tabindex="-1">三、接地电阻的要求(必背) <a class="header-anchor" href="#三、接地电阻的要求-必背" aria-label="Permalink to &quot;三、接地电阻的要求(必背)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场所</th><th>接地电阻要求</th></tr></thead><tbody><tr><td>一般低压设备<strong>保护接地</strong></td><td>不大于 <strong>4Ω</strong>(常见要求)</td></tr><tr><td>重复接地</td><td>一般不大于 <strong>10Ω</strong></td></tr><tr><td>独立避雷针(防雷接地)</td><td>一般不大于 <strong>10Ω</strong></td></tr><tr><td>大型电气设备 / 特殊要求</td><td>按规范(有的要求 1Ω 以下)</td></tr></tbody></table><blockquote><p>💡 记忆:<strong>保护接地 ≤4Ω,重复接地和防雷接地 ≤10Ω</strong>——接地电阻越小,泄流越痛快,越安全。</p></blockquote><h2 id="四、接地电阻的测量-接地摇表" tabindex="-1">四、接地电阻的测量(接地摇表) <a class="header-anchor" href="#四、接地电阻的测量-接地摇表" aria-label="Permalink to &quot;四、接地电阻的测量(接地摇表)&quot;">​</a></h2><p><strong>用接地电阻测量仪(接地摇表)测量接地电阻</strong>:</p><ul><li>测量时把测试极按规定的距离打人地下(T、P、C 三根引线);</li><li>摇动发电机(或按测量键),读取接地电阻值;</li><li><strong>测接地电阻必须断开被测量设备或线路</strong>(在停电/无负荷状态下测),以免干扰。</li></ul><blockquote><p>⚠️ 判断题高频:<strong>接地电阻用接地摇表(接地电阻测量仪)测量</strong>,不是万用表、不是兆欧表。</p></blockquote><h2 id="五、接地装置的检查与维护" tabindex="-1">五、接地装置的检查与维护 <a class="header-anchor" href="#五、接地装置的检查与维护" aria-label="Permalink to &quot;五、接地装置的检查与维护&quot;">​</a></h2><ul><li>定期测量<strong>接地电阻</strong>,不合格要整改(如增加接地体、换土、降阻);</li><li>检查接地线、焊点是否<strong>松动、锈蚀、断开</strong>;</li><li>有腐蚀性环境的接地装置要<strong>定期检查防腐</strong>;</li><li>检修接地装置时注意安全,接地系统是安全底线。</li></ul><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 接地装置 = 接地体 + 接地线,埋深、连接、防腐都要合格。</li><li>✅ 接地电阻:保护接地 ≤4Ω,重复/防雷接地 ≤10Ω。</li><li>✅ 测量用<strong>接地电阻测量仪(接地摇表)</strong>。</li><li>⚠️ 易混点:万用表测电压电流、兆欧表测绝缘电阻、接地摇表测接地电阻——三表职责不同。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>接地装置由接地体和接地线组成,负责把电流可靠泄入大地。</li><li>接地电阻要小(保护接地≤4Ω),埋深、防腐、连接可靠。</li><li>接地电阻定期用接地摇表测量,不合格要及时整改。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(判断)接地装置由接地体和接地线组成。( )</li><li>(单选)一般低压设备保护接地的接地电阻要求不大于()。 A. 4Ω　B. 10Ω　C. 100Ω　D. 1kΩ</li><li>(单选)测量接地电阻应使用()。 A. 万用表　B. 兆欧表　C. 接地电阻测量仪　D. 钳形电流表</li><li>(判断)接地体埋设深度要足够,连接处要可靠并做防腐处理。( )</li><li>(单选)重复接地的接地电阻一般要求不大于()。 A. 4Ω　B. 10Ω　C. 30Ω　D. 100Ω</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。接地装置 = 接地体 + 接地线。</li><li><strong>A</strong>。保护接地接地电阻不大于 4Ω。</li><li><strong>C</strong>。接地电阻用接地电阻测量仪(接地摇表)。</li><li><strong>√</strong>。埋深、连接、防腐是安装要求。</li><li><strong>B</strong>。重复接地一般不大于 10Ω。</li></ol></details>',25)])])}const b=a(r,[["render",o]]);export{u as __pageData,b as default};
